"use client";

import {
  ArrowLeftIcon,
  DownloadIcon,
  FileIcon,
  FolderIcon,
  FolderPlusIcon,
  PencilIcon,
  SearchIcon,
  Trash2Icon,
  UploadIcon,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";

import { Link } from "@/components/link";
import { driveLabels } from "@/components/plugins/drive/labels";
import type {
  DriveBrowserProps,
  DriveEntry,
  DriveFolderResult,
  DrivePageProps,
  DrivePageResult,
  DriveSpace,
} from "@/components/plugins/drive/types";
import {
  buttonClass,
  cardClass,
  DriveFeedback,
  EntryDialog,
  inputClass,
  messageFor,
  primaryClass,
} from "@/components/plugins/drive/ui";
import { useUploads } from "@/components/plugins/drive/use-uploads";
import { DriveError, safeDownloadUrl, scopeKey } from "@/components/plugins/drive/utils";
import { cn } from "@/components/utils/cn";

export type * from "@/components/plugins/drive/types";
export type { DriveLabels } from "@/components/plugins/drive/labels";
export type { DriveTransfer } from "@/components/plugins/drive/transfer";
export { transferDriveUpload } from "@/components/plugins/drive/transfer";
export { DriveError, DEFAULT_MAX_FILE_BYTES } from "@/components/plugins/drive/utils";

export function DrivePage({
  client,
  getSpaceHref,
  labels: overrides,
  linkComponent: HostLink = Link,
  className,
}: DrivePageProps) {
  const labels = { ...driveLabels, ...overrides };
  const [search, setSearch] = useState("");
  const [cursor, setCursor] = useState<string>();
  const [revision, setRevision] = useState(0);
  const request = useMemo(
    () => ({ client, search, cursor, revision }),
    [client, search, cursor, revision],
  );
  const [result, setResult] = useState<{
    request: typeof request;
    data?: DrivePageResult<DriveSpace>;
    error?: unknown;
  }>();
  const loading = result?.request !== request;
  const data = loading ? undefined : result?.data;
  const error = loading ? undefined : result?.error;
  useEffect(() => {
    const controller = new AbortController();
    void request.client
      .listSpaces({ search: request.search, cursor: request.cursor, signal: controller.signal })
      .then((data) => {
        if (!controller.signal.aborted) setResult({ request, data });
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) setResult({ request, error });
      });
    return () => controller.abort();
  }, [request]);
  return (
    <section
      className={cn("space-y-6 p-4 text-foreground md:p-8", className)}
      aria-label={labels.title}
    >
      <header>
        <h1 className="text-2xl font-semibold">{labels.title}</h1>
        <p className="mt-2 text-sm text-muted-foreground">{labels.description}</p>
      </header>
      <label className="relative block max-w-md">
        <SearchIcon
          className="absolute top-2 left-3 size-5 text-muted-foreground"
          aria-hidden="true"
        />
        <input
          type="search"
          aria-label={labels.searchSpaces}
          placeholder={labels.searchSpaces}
          className={cn(inputClass, "pl-10")}
          value={search}
          onChange={(event) => {
            setSearch(event.target.value);
            setCursor(undefined);
          }}
        />
      </label>
      <div className={cardClass} aria-busy={loading}>
        {loading ? (
          <DriveFeedback message={labels.loading} />
        ) : error ? (
          <>
            <DriveFeedback message={messageFor(error, labels)} error />
            <button className={buttonClass} onClick={() => setRevision((value) => value + 1)}>
              {labels.retry}
            </button>
          </>
        ) : !data?.items.length ? (
          <p className="text-sm text-muted-foreground">{labels.emptySpaces}</p>
        ) : (
          <ul aria-label={labels.spaces} className="divide-y divide-border">
            {data.items.map((space) => (
              <li
                key={scopeKey(space.scope)}
                className="flex flex-wrap items-center justify-between gap-3 py-4 first:pt-0 last:pb-0"
              >
                <HostLink
                  href={getSpaceHref(space)}
                  className={cn(buttonClass, "min-w-0 justify-start break-words")}
                >
                  <FolderIcon aria-hidden="true" />
                  {space.name}
                </HostLink>
                <div className="flex items-center gap-2">
                  {!Object.entries(space.capabilities).some(
                    ([key, value]) => key !== "download" && value,
                  ) && <span className="text-xs text-muted-foreground">{labels.readOnly}</span>}
                  {space.href && (
                    <HostLink href={space.href} className={buttonClass}>
                      {labels.openRecord}
                      <span className="sr-only">: {space.name}</span>
                    </HostLink>
                  )}
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
      <div className="flex gap-2">
        {cursor && (
          <button className={buttonClass} disabled={loading} onClick={() => setCursor(undefined)}>
            {labels.first}
          </button>
        )}
        {!error && data?.nextCursor && (
          <button
            className={buttonClass}
            disabled={loading}
            onClick={() => setCursor(data.nextCursor)}
          >
            {labels.next}
          </button>
        )}
      </div>
    </section>
  );
}

export function DriveBrowser(props: DriveBrowserProps) {
  return <Browser key={`${scopeKey(props.scope)}:${props.parentId ?? "root"}`} {...props} />;
}
function Browser({
  client,
  scope,
  parentId = null,
  getFolderHref,
  backHref,
  transferUpload,
  labels: overrides,
  linkComponent: HostLink = Link,
  locale,
  className,
}: DriveBrowserProps) {
  const labels = { ...driveLabels, ...overrides };
  const [search, setSearch] = useState("");
  const [cursor, setCursor] = useState<string>();
  const [revision, setRevision] = useState(0);
  const request = useMemo(
    () => ({ client, scope, parentId, search, cursor, revision }),
    [client, scope, parentId, search, cursor, revision],
  );
  const [result, setResult] = useState<{
    request: typeof request;
    data?: DriveFolderResult;
    error?: unknown;
  }>();
  const loading = result?.request !== request;
  const data = loading ? undefined : result?.data;
  const error = loading ? undefined : result?.error;
  const [feedback, setFeedback] = useState<{ message: string; error?: boolean }>();
  const [downloading, setDownloading] = useState(false);
  const downloadLock = useRef(false);
  const fileInput = useRef<HTMLInputElement>(null);
  const refresh = () => {
    setRevision((value) => value + 1);
  };
  const queue = useUploads(client, scope, parentId, refresh, transferUpload);
  useEffect(() => {
    const controller = new AbortController();
    void request.client
      .listEntries({
        scope: request.scope,
        parentId: request.parentId,
        search: request.search,
        cursor: request.cursor,
        signal: controller.signal,
      })
      .then((data) => {
        if (!controller.signal.aborted) setResult({ request, data });
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) setResult({ request, error });
      });
    return () => controller.abort();
  }, [request]);
  const capabilities = !loading && !error ? data?.space.capabilities : undefined;
  async function download(entry: DriveEntry) {
    if (downloadLock.current) return;
    downloadLock.current = true;
    setDownloading(true);
    setFeedback(undefined);
    try {
      const result = await client.getDownload({ scope, entryId: entry.id });
      const url = safeDownloadUrl(result.url);
      if (!url) throw new DriveError("INVALID");
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = entry.name;
      anchor.rel = "noopener";
      document.body.append(anchor);
      anchor.click();
      anchor.remove();
      setFeedback({ message: labels.downloading });
    } catch (reason) {
      setFeedback({ message: messageFor(reason, labels), error: true });
    } finally {
      downloadLock.current = false;
      setDownloading(false);
    }
  }
  return (
    <section className={cn("space-y-5 text-foreground", className)} aria-label={labels.title}>
      {backHref && (
        <HostLink href={backHref} className={buttonClass}>
          <ArrowLeftIcon aria-hidden="true" />
          {labels.back}
        </HostLink>
      )}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h2 className="text-xl font-semibold">{data?.space.name ?? labels.title}</h2>
        {data?.space.href && (
          <HostLink href={data.space.href} className={buttonClass}>
            {labels.openRecord}
          </HostLink>
        )}
      </div>
      <nav aria-label={labels.breadcrumbs}>
        <ol className="flex flex-wrap items-center gap-1 text-sm">
          <li>
            <HostLink
              href={getFolderHref(null)}
              className={buttonClass}
              aria-current={!parentId ? "page" : undefined}
            >
              {labels.root}
            </HostLink>
          </li>
          {data?.breadcrumbs.map((folder) => (
            <li key={folder.id} className="flex min-w-0 items-center gap-1">
              <span aria-hidden="true">/</span>
              <HostLink
                href={getFolderHref(folder.id)}
                className={cn(buttonClass, "break-all")}
                aria-current={folder.id === parentId ? "page" : undefined}
              >
                {folder.name}
              </HostLink>
            </li>
          ))}
        </ol>
      </nav>
      <div className="flex flex-wrap items-center gap-3">
        <input
          type="search"
          className={cn(inputClass, "max-w-md")}
          aria-label={labels.searchFiles}
          placeholder={labels.searchFiles}
          value={search}
          onChange={(event) => {
            setSearch(event.target.value);
            setCursor(undefined);
          }}
        />
        {capabilities?.createFolder && (
          <EntryDialog
            client={client}
            scope={scope}
            parentId={parentId}
            labels={labels}
            refresh={() => {
              refresh();
              setFeedback({ message: labels.saved });
            }}
          >
            <FolderPlusIcon aria-hidden="true" />
            {labels.newFolder}
          </EntryDialog>
        )}
        {capabilities?.upload && (
          <>
            <input
              ref={fileInput}
              type="file"
              multiple
              hidden
              onChange={(event) => {
                if (event.target.files && data)
                  queue.add(Array.from(event.target.files), data.maxFileBytes);
                event.target.value = "";
              }}
            />
            <button className={primaryClass} onClick={() => fileInput.current?.click()}>
              <UploadIcon aria-hidden="true" />
              {labels.upload}
            </button>
          </>
        )}
        {capabilities &&
          !capabilities.upload &&
          !capabilities.createFolder &&
          !capabilities.rename &&
          !capabilities.delete && (
            <span className="text-sm text-muted-foreground">{labels.readOnly}</span>
          )}
      </div>
      <DriveFeedback {...feedback} />
      <div
        className={cn(cardClass, "overflow-hidden")}
        aria-busy={loading}
        onDragOver={(event) => {
          if (capabilities?.upload) {
            event.preventDefault();
            event.dataTransfer.dropEffect = "copy";
          }
        }}
        onDrop={(event) => {
          event.preventDefault();
          if (!capabilities?.upload || !data) return;
          if (
            Array.from(event.dataTransfer.items).some(
              (item) => item.webkitGetAsEntry?.()?.isDirectory,
            )
          ) {
            setFeedback({ message: labels.folderDrop, error: true });
            return;
          }
          queue.add(Array.from(event.dataTransfer.files), data.maxFileBytes);
        }}
      >
        {capabilities?.upload && (
          <p className="mb-4 text-sm text-muted-foreground">
            {labels.drop} {data && labels.uploadLimit(data.maxFileBytes)}
          </p>
        )}
        {loading ? (
          <DriveFeedback message={labels.loading} />
        ) : error ? (
          <>
            <DriveFeedback message={messageFor(error, labels)} error />
            <button className={buttonClass} onClick={refresh}>
              {labels.retry}
            </button>
          </>
        ) : !data?.items.length ? (
          <p className="py-8 text-center text-sm text-muted-foreground">
            {search ? labels.noMatches : labels.empty}
          </p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead>
                <tr className="border-b border-border text-muted-foreground">
                  <th className="py-3 pr-4 font-medium">{labels.name}</th>
                  <th className="hidden px-3 py-3 font-medium sm:table-cell">{labels.size}</th>
                  <th className="hidden px-3 py-3 font-medium md:table-cell">{labels.modified}</th>
                  <th className="py-3 text-right font-medium">{labels.actions}</th>
                </tr>
              </thead>
              <tbody>
                {data.items.map((entry) => (
                  <tr key={entry.id} className="border-b border-border last:border-0">
                    <td className="max-w-[14rem] py-3 pr-3 sm:max-w-none">
                      <div className="flex items-center gap-2">
                        {entry.kind === "folder" ? (
                          <FolderIcon
                            className="size-5 shrink-0 text-muted-foreground"
                            aria-hidden="true"
                          />
                        ) : (
                          <FileIcon
                            className="size-5 shrink-0 text-muted-foreground"
                            aria-hidden="true"
                          />
                        )}
                        {entry.kind === "folder" && entry.state === "ready" ? (
                          <HostLink
                            href={getFolderHref(entry.id)}
                            className="rounded break-all hover:underline focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                          >
                            {entry.name}
                          </HostLink>
                        ) : (
                          <span className="break-all">{entry.name}</span>
                        )}
                      </div>
                      {entry.state === "deleting" && (
                        <output className="mt-1 block text-xs text-muted-foreground">
                          {labels.deleting}
                        </output>
                      )}
                    </td>
                    <td className="hidden px-3 py-3 whitespace-nowrap text-muted-foreground sm:table-cell">
                      {entry.kind === "folder"
                        ? labels.folder
                        : new Intl.NumberFormat(locale, {
                            style: "unit",
                            unit:
                              entry.size >= 1_000_000
                                ? "megabyte"
                                : entry.size >= 1000
                                  ? "kilobyte"
                                  : "byte",
                            maximumFractionDigits: 1,
                          }).format(
                            entry.size /
                              (entry.size >= 1_000_000 ? 1_000_000 : entry.size >= 1000 ? 1000 : 1),
                          )}
                    </td>
                    <td className="hidden px-3 py-3 whitespace-nowrap text-muted-foreground md:table-cell">
                      <time dateTime={entry.updatedAt}>
                        {new Intl.DateTimeFormat(locale, {
                          dateStyle: "medium",
                          timeZone: "UTC",
                        }).format(new Date(entry.updatedAt))}
                      </time>
                    </td>
                    <td className="py-3">
                      <div className="flex justify-end">
                        {entry.state === "ready" &&
                          capabilities?.download &&
                          entry.kind === "file" && (
                            <button
                              className={buttonClass}
                              aria-label={labels.download}
                              disabled={downloading}
                              onClick={() => void download(entry)}
                            >
                              <DownloadIcon aria-hidden="true" />
                            </button>
                          )}
                        {entry.state === "ready" && capabilities?.rename && (
                          <EntryDialog
                            client={client}
                            scope={scope}
                            parentId={parentId}
                            entry={entry}
                            labels={labels}
                            refresh={() => {
                              refresh();
                              setFeedback({ message: labels.saved });
                            }}
                          >
                            <PencilIcon aria-hidden="true" />
                          </EntryDialog>
                        )}
                        {capabilities?.delete && (
                          <EntryDialog
                            client={client}
                            scope={scope}
                            parentId={parentId}
                            entry={entry}
                            deleting
                            labels={labels}
                            refresh={() => {
                              refresh();
                              setFeedback({ message: labels.saved });
                            }}
                          >
                            <Trash2Icon aria-hidden="true" />
                          </EntryDialog>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
      <div className="flex gap-2">
        {cursor && (
          <button className={buttonClass} disabled={loading} onClick={() => setCursor(undefined)}>
            {labels.first}
          </button>
        )}
        {!error && data?.nextCursor && (
          <button
            className={buttonClass}
            disabled={loading}
            onClick={() => setCursor(data.nextCursor)}
          >
            {labels.next}
          </button>
        )}
      </div>
      {queue.uploads.length > 0 && (
        <div className={cn(cardClass, "space-y-4")}>
          <h3 className="font-semibold">{labels.uploads}</h3>
          <ul className="space-y-4">
            {queue.uploads.map((upload) => (
              <li key={upload.id} className="space-y-2">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <span className="min-w-0 text-sm break-all">{upload.file.name}</span>
                  <div className="flex items-center gap-1">
                    {["failed", "cancelFailed"].includes(upload.state) && (
                      <button className={buttonClass} onClick={() => queue.retry(upload.id)}>
                        {labels.retry}
                      </button>
                    )}
                    {["queued", "uploading", "failed"].includes(upload.state) && (
                      <button className={buttonClass} onClick={() => queue.cancel(upload.id)}>
                        {labels.cancel}
                      </button>
                    )}
                    {["done", "cancelled"].includes(upload.state) && (
                      <button className={buttonClass} onClick={() => queue.dismiss(upload.id)}>
                        {labels.dismiss}
                      </button>
                    )}
                  </div>
                </div>
                <progress
                  className="h-2 w-full accent-primary"
                  max={100}
                  value={upload.progress}
                  aria-label={labels.progress(upload.file.name)}
                />
                <DriveFeedback
                  message={labels[upload.state]}
                  error={upload.state === "failed" || upload.state === "cancelFailed"}
                />
                {upload.error !== undefined && (
                  <DriveFeedback message={messageFor(upload.error, labels)} error />
                )}
              </li>
            ))}
          </ul>
        </div>
      )}
    </section>
  );
}

import type { DriveUploadTicket } from "@/components/plugins/drive/types";
import { DriveError } from "@/components/plugins/drive/utils";

export type DriveTransfer = (
  ticket: DriveUploadTicket,
  file: File,
  options: { signal: AbortSignal; onProgress: (percent: number) => void },
) => Promise<void>;

/** Direct browser PUT. The storage URL must permit the host origin through CORS. */
export const transferDriveUpload: DriveTransfer = (ticket, file, { signal, onProgress }) =>
  new Promise((resolve, reject) => {
    if (!ticket.url || signal.aborted) {
      reject(new DriveError("STORAGE"));
      return;
    }
    const xhr = new XMLHttpRequest();
    const abort = () => xhr.abort();
    const finish = (error?: Error) => {
      signal.removeEventListener("abort", abort);
      if (error) reject(error);
      else resolve();
    };
    xhr.open("PUT", ticket.url);
    for (const [name, value] of Object.entries(ticket.headers ?? {}))
      xhr.setRequestHeader(name, value);
    xhr.upload.onprogress = (event) => {
      if (event.lengthComputable) onProgress(Math.round((event.loaded / event.total) * 100));
    };
    // A retry may find an already uploaded staging object. Completion verifies it.
    xhr.onload = () =>
      finish(
        (xhr.status >= 200 && xhr.status < 300) || xhr.status === 412
          ? undefined
          : new DriveError("STORAGE"),
      );
    xhr.onerror = () => finish(new DriveError("STORAGE"));
    xhr.onabort = () => finish(new DOMException("Aborted", "AbortError"));
    signal.addEventListener("abort", abort, { once: true });
    xhr.send(file);
  });

import type { ComponentType } from "react";

import type { LinkProps } from "@/components/link";
import type { DriveLabels } from "@/components/plugins/drive/labels";
import type { DriveTransfer } from "@/components/plugins/drive/transfer";

export interface DriveScope {
  type: string;
  id: string;
}
export interface DriveCapabilities {
  upload: boolean;
  createFolder: boolean;
  rename: boolean;
  delete: boolean;
  download: boolean;
}
export interface DriveSpace {
  scope: DriveScope;
  name: string;
  href?: string;
  capabilities: DriveCapabilities;
}
export interface DriveEntry {
  id: string;
  parentId: string | null;
  kind: "file" | "folder";
  name: string;
  size: number;
  contentType: string;
  updatedAt: string;
  state: "ready" | "deleting";
}
export interface DrivePageResult<T> {
  items: T[];
  nextCursor?: string;
}
export interface DriveQuery {
  search?: string;
  cursor?: string;
  signal?: AbortSignal;
}
export interface DriveFolderResult extends DrivePageResult<DriveEntry> {
  space: DriveSpace;
  breadcrumbs: { id: string; name: string }[];
  maxFileBytes: number;
}
export interface DriveUploadInput {
  scope: DriveScope;
  parentId: string | null;
  requestId: string;
  name: string;
  size: number;
  contentType: string;
}
export interface DriveUploadTicket {
  id: string;
  url?: string;
  headers?: Record<string, string>;
  expiresAt?: string;
  completed: boolean;
}
export interface DriveDeletePreview {
  token: string;
  files: number;
  folders: number;
}
export interface DriveClient {
  listSpaces(query: DriveQuery): Promise<DrivePageResult<DriveSpace>>;
  listEntries(
    input: DriveQuery & { scope: DriveScope; parentId: string | null },
  ): Promise<DriveFolderResult>;
  createFolder(input: { scope: DriveScope; parentId: string | null; name: string }): Promise<void>;
  rename(input: { scope: DriveScope; entryId: string; name: string }): Promise<void>;
  previewDelete(input: { scope: DriveScope; entryId: string }): Promise<DriveDeletePreview>;
  deleteEntry(input: { scope: DriveScope; entryId: string; token: string }): Promise<void>;
  prepareUpload(input: DriveUploadInput): Promise<DriveUploadTicket>;
  completeUpload(input: { scope: DriveScope; uploadId: string }): Promise<void>;
  cancelUpload(input: { scope: DriveScope; uploadId: string }): Promise<void>;
  getDownload(input: { scope: DriveScope; entryId: string }): Promise<{ url: string }>;
}
export interface DriveAppearanceProps {
  className?: string;
  labels?: Partial<DriveLabels>;
  linkComponent?: ComponentType<LinkProps>;
  locale?: string;
}
export interface DrivePageProps extends DriveAppearanceProps {
  client: DriveClient;
  getSpaceHref: (space: DriveSpace) => string;
}
export interface DriveBrowserProps extends DriveAppearanceProps {
  client: DriveClient;
  scope: DriveScope;
  parentId?: string | null;
  getFolderHref: (folderId: string | null) => string;
  backHref?: string;
  transferUpload?: DriveTransfer;
}

"use client";

import { Dialog } from "@base-ui/react/dialog";
import { useId, useRef, useState, type ReactNode } from "react";

import type { DriveLabels } from "@/components/plugins/drive/labels";
import type {
  DriveClient,
  DriveDeletePreview,
  DriveEntry,
  DriveScope,
} from "@/components/plugins/drive/types";
import { errorCode, validName } from "@/components/plugins/drive/utils";
import { cn } from "@/components/utils/cn";

export const buttonClass =
  "inline-flex min-h-9 items-center justify-center gap-2 rounded-2xl px-3 py-2 text-sm font-medium hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50 disabled:cursor-not-allowed [&_svg]:size-4";
export const primaryClass = cn(
  buttonClass,
  "bg-primary text-primary-foreground hover:bg-primary/90",
);
export const inputClass =
  "h-9 w-full min-w-0 rounded-2xl border border-transparent bg-muted px-3 text-base text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring md:text-sm";
export const cardClass = "rounded-3xl border border-border bg-background p-5 text-foreground";
export const messageFor = (error: unknown, labels: DriveLabels) =>
  labels[errorCode(error) ?? "error"];

export function DriveFeedback({ message, error = false }: { message?: string; error?: boolean }) {
  return message ? (
    <p
      role={error ? "alert" : "status"}
      className={cn("text-sm", error ? "text-destructive" : "text-muted-foreground")}
    >
      {message}
    </p>
  ) : null;
}

export function EntryDialog({
  client,
  scope,
  parentId,
  entry,
  deleting = false,
  labels,
  refresh,
  children,
}: {
  client: DriveClient;
  scope: DriveScope;
  parentId: string | null;
  entry?: DriveEntry;
  deleting?: boolean;
  labels: DriveLabels;
  refresh: () => void;
  children: ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const [name, setName] = useState(entry?.name ?? "");
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string>();
  const [preview, setPreview] = useState<DriveDeletePreview>();
  const lock = useRef(false);
  const fieldId = useId();
  const title = deleting ? labels.deleteTitle : entry ? labels.rename : labels.newFolder;
  async function loadPreview() {
    if (!entry || lock.current) return;
    lock.current = true;
    setPending(true);
    setError(undefined);
    setPreview(undefined);
    try {
      setPreview(await client.previewDelete({ scope, entryId: entry.id }));
    } catch (reason) {
      setError(messageFor(reason, labels));
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  async function submit() {
    if (lock.current || (deleting && !preview)) return;
    lock.current = true;
    setPending(true);
    setError(undefined);
    try {
      if (deleting && entry && preview)
        await client.deleteEntry({ scope, entryId: entry.id, token: preview.token });
      else if (entry) await client.rename({ scope, entryId: entry.id, name: validName(name) });
      else await client.createFolder({ scope, parentId, name: validName(name) });
      setOpen(false);
      refresh();
    } catch (reason) {
      setError(messageFor(reason, labels));
      if (deleting && errorCode(reason) === "CONFLICT") setPreview(undefined);
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  return (
    <Dialog.Root
      open={open}
      onOpenChange={(next) => {
        if (lock.current) return;
        setOpen(next);
        if (next) {
          setName(entry?.name ?? "");
          setError(undefined);
          if (deleting) void loadPreview();
        }
      }}
    >
      <Dialog.Trigger
        className={buttonClass}
        aria-label={deleting ? labels.delete : entry ? labels.rename : labels.newFolder}
      >
        {children}
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup
          className={cn(
            cardClass,
            "fixed top-1/2 left-1/2 z-50 w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 space-y-5 shadow-xl",
          )}
        >
          <Dialog.Title className="text-lg font-semibold">{title}</Dialog.Title>
          <Dialog.Description className="text-sm text-muted-foreground">
            {deleting
              ? preview && entry
                ? labels.deleteDescription(entry.name, preview.files, preview.folders)
                : labels.loading
              : labels.nameHint}
          </Dialog.Description>
          <form
            onSubmit={(event) => {
              event.preventDefault();
              void submit();
            }}
            className="space-y-4"
          >
            {!deleting && (
              <div className="space-y-2">
                <label htmlFor={fieldId} className="text-sm font-medium">
                  {labels.name}
                </label>
                <input
                  id={fieldId}
                  className={inputClass}
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                  maxLength={255}
                  required
                  disabled={pending}
                />
              </div>
            )}
            <DriveFeedback message={error} error />
            <div className="flex justify-end gap-2">
              <Dialog.Close className={buttonClass} disabled={pending}>
                {labels.cancel}
              </Dialog.Close>
              {deleting && !preview ? (
                <button
                  type="button"
                  className={primaryClass}
                  disabled={pending}
                  onClick={() => void loadPreview()}
                >
                  {pending ? labels.pending : labels.retry}
                </button>
              ) : (
                <button
                  type="submit"
                  className={cn(
                    primaryClass,
                    deleting &&
                      "bg-destructive text-destructive-foreground hover:bg-destructive/90",
                  )}
                  disabled={pending}
                >
                  {pending
                    ? labels.pending
                    : deleting
                      ? labels.confirmDelete
                      : entry
                        ? labels.save
                        : labels.create}
                </button>
              )}
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

import type { DriveTransfer } from "@/components/plugins/drive/transfer";
import { transferDriveUpload } from "@/components/plugins/drive/transfer";
import type { DriveClient, DriveScope } from "@/components/plugins/drive/types";
import { DriveError, errorCode } from "@/components/plugins/drive/utils";

type State =
  | "queued"
  | "uploading"
  | "finishing"
  | "done"
  | "failed"
  | "cancelled"
  | "cancelling"
  | "cancelFailed";
interface Job {
  id: string;
  file: File;
  state: State;
  progress: number;
  error?: unknown;
  controller: AbortController;
  reserved: boolean;
  busy: boolean;
  cancelled: boolean;
}
export function useUploads(
  client: DriveClient,
  scope: DriveScope,
  parentId: string | null,
  refresh: () => void,
  transfer: DriveTransfer = transferDriveUpload,
) {
  const jobs = useRef<Job[]>([]);
  const mounted = useRef(true);
  const [uploads, setUploads] = useState<Job[]>([]);
  const publish = () => {
    if (mounted.current) setUploads(jobs.current.map((job) => ({ ...job })));
  };
  async function abandon(job: Job) {
    job.state = "cancelling";
    publish();
    try {
      if (job.reserved) await client.cancelUpload({ scope, uploadId: job.id });
      job.state = "cancelled";
    } catch (error) {
      job.state = errorCode(error) === "NOT_FOUND" ? "cancelled" : "cancelFailed";
      job.error = job.state === "cancelled" ? undefined : error;
    }
    publish();
  }
  async function run(job: Job) {
    job.busy = true;
    job.state = "uploading";
    job.error = undefined;
    publish();
    try {
      // Mark before preparation: a lost preparation response may still reserve a file.
      job.reserved = true;
      const ticket = await client.prepareUpload({
        scope,
        parentId,
        requestId: job.id,
        name: job.file.name,
        size: job.file.size,
        contentType: job.file.type,
      });
      if (job.cancelled) {
        await abandon(job);
        return;
      }
      if (!ticket.completed) {
        try {
          await transfer(ticket, job.file, {
            signal: job.controller.signal,
            onProgress: (value) => {
              job.progress = value;
              publish();
            },
          });
        } catch (error) {
          if (job.cancelled) throw error;
          // A dropped PUT response is uncertain; the server can verify whether it arrived.
          job.state = "finishing";
          publish();
          await client.completeUpload({ scope, uploadId: job.id });
          job.state = "done";
          job.progress = 100;
          if (mounted.current) refresh();
          return;
        }
        if (job.cancelled) {
          await abandon(job);
          return;
        }
        job.state = "finishing";
        publish();
        await client.completeUpload({ scope, uploadId: job.id });
      }
      job.state = "done";
      job.progress = 100;
      if (mounted.current) refresh();
    } catch (error) {
      if (job.cancelled) await abandon(job);
      else {
        job.state = "failed";
        job.error = error;
      }
    } finally {
      job.busy = false;
      publish();
      pump();
    }
  }
  function pump() {
    if (!mounted.current) return;
    let active = jobs.current.filter((job) => job.busy).length;
    for (const job of jobs.current) {
      if (active >= 2) break;
      if (job.state === "queued") {
        active++;
        void run(job);
      }
    }
  }
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      for (const job of jobs.current) {
        if (["done", "cancelled"].includes(job.state)) continue;
        job.cancelled = true;
        job.controller.abort();
        if (!job.busy) void abandon(job);
      }
    };
    // This hook is owned by a browser keyed to its space and folder.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return {
    uploads,
    add(files: File[], maxBytes: number) {
      for (const file of files)
        jobs.current.push({
          id: crypto.randomUUID(),
          file,
          state: file.size > maxBytes ? "failed" : "queued",
          error: file.size > maxBytes ? new DriveError("INVALID") : undefined,
          progress: 0,
          controller: new AbortController(),
          reserved: false,
          busy: false,
          cancelled: false,
        });
      publish();
      pump();
    },
    cancel(id: string) {
      const job = jobs.current.find((item) => item.id === id);
      if (!job || job.state === "finishing" || job.state === "done") return;
      job.cancelled = true;
      job.controller.abort();
      if (!job.busy) void abandon(job);
      else {
        job.state = "cancelling";
        publish();
      }
    },
    retry(id: string) {
      const job = jobs.current.find((item) => item.id === id);
      if (!job || job.busy) return;
      if (job.state === "cancelFailed") {
        void abandon(job);
        return;
      }
      if (job.state !== "failed") return;
      job.controller = new AbortController();
      job.cancelled = false;
      job.state = "queued";
      job.progress = 0;
      publish();
      pump();
    },
    dismiss(id: string) {
      jobs.current = jobs.current.filter(
        (job) => job.id !== id || !["done", "cancelled"].includes(job.state),
      );
      publish();
    },
  };
}

import type { DriveScope } from "@/components/plugins/drive/types";
export const DEFAULT_MAX_FILE_BYTES = 100_000_000;
export const scopeKey = (scope: DriveScope) => JSON.stringify([scope.type, scope.id]);
export type DriveErrorCode =
  | "INVALID"
  | "NOT_FOUND"
  | "FORBIDDEN"
  | "CONFLICT"
  | "EXPIRED"
  | "DELETE_PENDING"
  | "STORAGE";
export class DriveError extends Error {
  readonly code: DriveErrorCode;
  constructor(code: DriveErrorCode) {
    super(code);
    this.name = "DriveError";
    this.code = code;
  }
}
export function validName(input: string) {
  if (typeof input !== "string") throw new DriveError("INVALID");
  const name = input.trim();
  if (
    !name ||
    name.length > 255 ||
    name === "." ||
    name === ".." ||
    /[/\\]/.test(name) ||
    name.split("").some((char) => char.charCodeAt(0) < 32 || char.charCodeAt(0) === 127)
  )
    throw new DriveError("INVALID");
  return name;
}
export function validScope(scope: DriveScope) {
  if (
    !scope ||
    typeof scope.type !== "string" ||
    typeof scope.id !== "string" ||
    !scope.type.trim() ||
    !scope.id.trim() ||
    scope.type.length > 100 ||
    scope.id.length > 512
  )
    throw new DriveError("INVALID");
  return scope;
}
export function validId(id: string) {
  if (
    typeof id !== "string" ||
    !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)
  )
    throw new DriveError("INVALID");
  return id;
}
export function errorCode(error: unknown): DriveErrorCode | undefined {
  if (
    error &&
    typeof error === "object" &&
    "code" in error &&
    typeof error.code === "string" &&
    [
      "INVALID",
      "NOT_FOUND",
      "FORBIDDEN",
      "CONFLICT",
      "EXPIRED",
      "DELETE_PENDING",
      "STORAGE",
    ].includes(error.code)
  )
    return error.code as DriveErrorCode;
}
export function safeDownloadUrl(input: string) {
  try {
    const url = new URL(input);
    return ["http:", "https:", "blob:"].includes(url.protocol) && !url.username && !url.password
      ? input
      : undefined;
  } catch {
    return undefined;
  }
}
